   259  bool PLY::Element::ParseElement(IOStreamBuffer<char> &streamBuffer, std::vector<char> &buffer, PLY::Element *pOut) {
   260      ai_assert(nullptr != pOut);
   261      // Example format: "element vertex 8"
   262
   263      // skip leading spaces
   264      if (!PLY::DOM::SkipSpaces(buffer)) {
   265          return false;
   266      }
   267
   268      // skip the "element" string at the beginning
   269      if (!PLY::DOM::TokenMatch(buffer, "element", 7) && !PLY::DOM::TokenMatch(buffer, "comment", 7)) {
   270          // seems not to be a valid property entry
   271          return false;
   272      }
   273      // get next word
   274      if (!PLY::DOM::SkipSpaces(buffer))
   275          return false;
   276
   277      // parse the semantic of the element
   278      pOut->eSemantic = PLY::Element::ParseSemantic(buffer);
   279      if (PLY::EEST_INVALID == pOut->eSemantic) {
   280          // if the exact semantic can't be determined, just store
   281          // the original string identifier
   282          pOut->szName = std::string(&buffer[0], &buffer[0] + strlen(&buffer[0]));
   283      }
   284
   285      if (!PLY::DOM::SkipSpaces(buffer))
   286          return false;
   287
   288      if (PLY::EEST_TextureFile == pOut->eSemantic) {
   289          char *endPos = &buffer[0] + (strlen(&buffer[0]) - 1);
   290          pOut->szName = std::string(&buffer[0], endPos);
   291
   292          // go to the next line
   293          PLY::DOM::SkipSpacesAndLineEnd(buffer);
   294
   295          return true;
   296      }
   297
   298      //parse the number of occurrences of this element
   299      const char *pCur = (char *)&buffer[0];
   300      pOut->NumOccur = strtoul10(pCur, &pCur);
   301
   302      // go to the next line
   303      PLY::DOM::SkipSpacesAndLineEnd(buffer);
   304
   305      // now parse all properties of the element
   306      while (true) {
   307          streamBuffer.getNextLine(buffer);
   308          pCur = (char *)&buffer[0];
   309
   310          // skip all comments
   311          PLY::DOM::SkipComments(buffer);
   312
   313          PLY::Property prop;
   314          if (!PLY::Property::ParseProperty(buffer, &prop))
   315              break;
   316
   317          pOut->alProperties.push_back(prop);
   318      }
   319
   320      return true;
   321  }
