   324  bool PLY::DOM::SkipSpaces(std::vector<char> &buffer) {
   325      const char *pCur = buffer.empty() ? nullptr : (char *)&buffer[0];
   326      bool ret = false;
   327      if (pCur) {
   328          const char *szCur = pCur;
   329          ret = Assimp::SkipSpaces(pCur, &pCur);
   330
   331          uintptr_t iDiff = (uintptr_t)pCur - (uintptr_t)szCur;
   332          buffer.erase(buffer.begin(), buffer.begin() + iDiff);
   333          return ret;
   334      }
   335
   336      return ret;
   337  }
