   384  bool PLY::DOM::SkipComments(std::vector<char> &buffer) {
   385      ai_assert(!buffer.empty());
   386
   387      std::vector<char> nbuffer = buffer;
   388      // skip spaces
   389      if (!SkipSpaces(nbuffer)) {
   390          return false;
   391      }
   392
   393      if (TokenMatch(nbuffer, "comment", 7)) {
   394          if (!SkipSpaces(nbuffer))
   395              SkipLine(nbuffer);
   396
   397          if (!TokenMatch(nbuffer, "TextureFile", 11)) {
   398              SkipLine(nbuffer);
   399              buffer = nbuffer;
   400              return true;
   401          }
   402
   403          return true;
   404      }
   405
   406      return false;
   407  }
