   410  bool PLY::DOM::ParseHeader(IOStreamBuffer<char> &streamBuffer, std::vector<char> &buffer, bool isBinary) {
   411      ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseHeader() begin");
   412
   413      // parse all elements
   414      while (!buffer.empty()) {
   415          // skip all comments
   416          PLY::DOM::SkipComments(buffer);
   417
   418          PLY::Element out;
   419          if (PLY::Element::ParseElement(streamBuffer, buffer, &out)) {
   420              // add the element to the list of elements
   421              alElements.push_back(out);
   422          } else if (TokenMatch(buffer, "end_header", 10)) { //checks for /n ending, if it doesn't end with /r/n
   423              // we have reached the end of the header
   424              break;
   425          } else {
   426              // ignore unknown header elements
   427              streamBuffer.getNextLine(buffer);
   428          }
   429      }
   430
   431      if (!isBinary) // it would occur an error, if binary data start with values as space or line end.
   432          SkipSpacesAndLineEnd(buffer);
   433
   434      ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseHeader() succeeded");
   435      return true;
   436  }
