   439  bool PLY::DOM::ParseElementInstanceLists(IOStreamBuffer<char> &streamBuffer, std::vector<char> &buffer, PLYImporter *loader) {
   440      ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseElementInstanceLists() begin");
   441      alElementData.resize(alElements.size());
   442
   443      std::vector<PLY::Element>::const_iterator i = alElements.begin();
   444      std::vector<PLY::ElementInstanceList>::iterator a = alElementData.begin();
   445
   446      // parse all element instances
   447      //construct vertices and faces
   448      for (; i != alElements.end(); ++i, ++a) {
   449          if ((*i).eSemantic == EEST_Vertex || (*i).eSemantic == EEST_Face || (*i).eSemantic == EEST_TriStrip) {
   450              PLY::ElementInstanceList::ParseInstanceList(streamBuffer, buffer, &(*i), nullptr, loader);
   451          } else {
   452              (*a).alInstances.resize((*i).NumOccur);
   453              PLY::ElementInstanceList::ParseInstanceList(streamBuffer, buffer, &(*i), &(*a), nullptr);
   454          }
   455      }
   456
   457      ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseElementInstanceLists() succeeded");
   458      return true;
   459  }
