   488  bool PLY::DOM::ParseInstanceBinary(IOStreamBuffer<char> &streamBuffer, DOM *p_pcOut, PLYImporter *loader, bool p_bBE) {
   489      ai_assert(nullptr != p_pcOut);
   490      ai_assert(nullptr != loader);
   491
   492      std::vector<char> buffer;
   493      streamBuffer.getNextLine(buffer);
   494
   495      ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseInstanceBinary() begin");
   496
   497      if (!p_pcOut->ParseHeader(streamBuffer, buffer, true)) {
   498          ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseInstanceBinary() failure");
   499          return false;
   500      }
   501
   502      streamBuffer.getNextBlock(buffer);
   503
   504      // remove first char if it's /n in case of file with /r/n
   505      if (((char *)&buffer[0])[0] == '\n')
   506          buffer.erase(buffer.begin(), buffer.begin() + 1);
   507
   508      unsigned int bufferSize = static_cast<unsigned int>(buffer.size());
   509      const char *pCur = (char *)&buffer[0];
   510      if (!p_pcOut->ParseElementInstanceListsBinary(streamBuffer, buffer, pCur, bufferSize, loader, p_bBE)) {
   511          ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseInstanceBinary() failure");
   512          return false;
   513      }
   514      ASSIMP_LOG_VERBOSE_DEBUG("PLY::DOM::ParseInstanceBinary() succeeded");
   515      return true;
   516  }
